// Special Power Ups
class PowerUp {
    constructor(x, y, speedX, speedY, movement, range, xbreak) {
        this.image = mainSprites;
        this.isPowerUp = true;
        this.width = 80;
        this.height = 70;
        this.x = x;
        this.y = y;
        this.spriteSize = 150;
        this.maxFrames = 2;
        this.frameXStart = 4;
        this.frameY = 6;
        if (isLevelDark) this.frameY = 7;
        this.frameX = this.frameXStart;
        this.delete = false;      // powerUp marked for deletion;
        this.speedX = speedX;
        this.speedY = speedY;
        this.movement = movement;
        this.range = range;
        this.xbreak = xbreak;
        this.angle = 0;
        this.spriteTimer = 0;     //sprite animation helper
        this.spriteInterval = 300;
        this.hit = false;  // flag for single collision else multiple power added

        //randomizing the power up awarded to the player
        this.randomize = Math.random();
        if (this.randomize < 0.25) this.powerup = "life";
        else if (this.randomize < 0.5) this.powerup = "missile";
        else if (this.randomize < 0.75) this.powerup = "laser";
        else this.powerup = "wall";
    }
    update(deltaTime) {
        constrainActor(this);
        //sprite animation
        if (this.spriteTimer > this.spriteInterval) {
            this.frameX++;
            if (this.frameX - this.frameXStart >= this.maxFrames) this.frameX = this.frameXStart;
            this.spriteTimer = 0;
        } else this.spriteTimer += deltaTime;

        //movement
        switch (this.movement) {
            case "wave":
                this.x -= this.speedX;
                this.y = wavePosition(this);
                this.angle += this.speedY;
                break;

            case "linear":
            default:
                this.x -= this.speedX;
        }

        constrainActor(this);
        if(currentLevel.number===10&&!this.isPowerUp&&currentLevel.background.some(bg=>bg.hitbox.some(hb=>checkCollision(this,hb)))){
            this.delete=true;currentLevel.explosions.push(new Explosion(this.x,this.y));return;
        }
        // garbage collection
        if (this.x + this.width < 0) this.delete = true;

        this.draw();
    }
    draw() {
        mainCtx.drawImage(this.image, this.frameX * this.spriteSize, this.frameY * this.spriteSize, this.width, this.height, this.x, this.y, this.width, this.height);
    }
}
// Exact native 14x7 sheets: two 7x7 poses, no interpolation.
const PICKUP_SPRITES={"ammo":["10101000101010","00000101000001","10110010011000","00111001011101","10110010011000","00000101000001","10101000101010"],"life":["01010100010100","00000001000001","10101010010100","00111001011101","10010010001000","00000000100010","00101000001000"],"missile":["10101000101000","00000101000101","10100010010000","00111001011101","10100010010000","00000101000101","10101000101000"],"laser":["00000000000000","01010100010100","10000010000000","00111001011101","10000010000000","01010100010100","00000000000000"],"wall":["10101010101010","00000001000001","10101010010100","00101001010101","10101010010100","00000001000001","10101010101010"],"bonus":["10101010101010","00000001000001","10111010011100","00101001010101","10111010011100","00000001000001","10101010101010"]};
class Supply extends PowerUp {
 constructor(kind,amount,y){super(840,y,3,0,'linear',0,0);this.powerup=kind;this.amount=amount;this.width=70;this.height=70;this.age=0;}
 update(dt){this.age+=dt;super.update(dt);}
 draw(){const rows=PICKUP_SPRITES[this.powerup],offset=(Math.floor(this.age/200)%2)*7;for(let y=0;y<7;y++)for(let x=0;x<7;x++)if(rows[y][x+offset]==='1')mainCtx.fillRect(this.x+x*10,this.y+y*10,10,10);}
}
function configureSupplies(level){
 const bossTime=level.sourceEnemyArray.find(w=>w.object.some(e=>e.isBoss))?.time||52000;
 // Old random drops are replaced with known supplies; budgets include the starting magazine.
 level.sourceEnemyArray.forEach(w=>{w.object=w.object.filter(e=>!e.isPowerUp);});
 const total=BALANCE.supply[level.number-1]-(level.number===1?BALANCE.startAmmo:0);
 const early=level.number===1?2500:1000,middle=Math.max(3000,bossTime*.4),late=Math.max(6000,bossTime-9000);
 const a=Math.floor(total*.35),b=Math.floor(total*.35);
 const y=level.number===11?100:PLAYFIELD_TOP+60;
 [early,middle,late].forEach((time,i)=>level.sourceEnemyArray.push({time,object:[new Supply('ammo',[a,b,total-a-b][i],y+(i%2)*40)]}));
 const weapon=['missile','laser','wall'][(level.number-1)%3];
 level.sourceEnemyArray.push({time:Math.max(4000,bossTime*.55),object:[new Supply(weapon,weapon==='wall'?1:3,y+70)]});
 if([3,6,9].includes(level.number))level.sourceEnemyArray.push({time:bossTime*.7,object:[new Supply('life',1,y)]});
 if(level.number===9&&!bonusUsed)level.sourceEnemyArray.push({time:18000,object:[new Supply('bonus',0,230)]});
 level.sourceEnemyArray.sort((a,b)=>a.time-b.time);
}
function frameSprite(index){return options.frames?.[index%(options.frames?.length||1)]||{width:12,height:12,rows:Array.from({length:12},(_,y)=>y<2||y>9?'111111111111':'110000000011')};}
function drawFrame(entry,x,y,ctx){const invert=entry.hits%2===1;const rows=entry.sprite.rows.map(row=>invert?[...row].map(p=>p==='1'?'0':'1').join(''):row);
 ctx.drawImage({...entry.sprite,rows},0,0,120,120,x*10,y*10,120,120);
}
function hitFrame(entry,shots,x,y,gallery=false){
 const box={x:x*10,y:y*10,width:120,height:120};
 const requiredHits=gallery?1:10;
 for(const shot of shots){if(entry.hits>=requiredHits)break;if(shot.delete)continue;if(checkCollision(shot,box)){markShotHit(shot);shot.delete=true;entry.hits++;
  const multiplier=gallery&&hasArchetype('Collector')?2:1;
  const points=multiplier+(entry.hits===requiredHits?(gallery?GALLERY_FRAME_BONUS:BALANCE.frameBonus)*multiplier:0);
  playerScore+=points;if(gallery)galleryMetrics.points+=points;
  if(entry.hits===requiredHits){if(gallery)galleryMetrics.frames++;else if(currentLevel.metrics)currentLevel.metrics.frames++;}
  sound('pickup');}}
}
function beginBonus(){clearKeys();shotCooldown=0;bonus={remaining:BALANCE.bonusMs,ammo:BALANCE.bonusAmmo,player:new Player(currentLevel),shots:[],frames:[],spawn:0,index:0,scoreAtStart:playerScore};bonus.player.x=10;bonus.player.y=200;recordEvent('gallery-start','GALLERY: 100 SEPARATE ROUNDS');}
function updateBonus(dt){
 bonus.remaining-=dt;bonus.spawn-=dt;
 if(bonus.spawn<=0){bonus.spawn+=900;for(let j=0;j<3;j++)bonus.frames.push({sprite:frameSprite(bonus.index++),x:84,y:9+j*12,hits:0});}
 bonus.player.update(dt);bonus.shots.forEach(s=>s.update());
 for(const f of bonus.frames){f.x-=dt*.015;hitFrame(f,bonus.shots,Math.round(f.x),f.y,true);if(f.hits<1)drawFrame(f,Math.round(f.x),f.y,bgCtx);}
 bonus.frames=bonus.frames.filter(f=>f.x+12>0&&f.hits<1);bonus.shots=bonus.shots.filter(s=>!s.delete);
 if(bonus.remaining<=0){const points=playerScore-bonus.scoreAtStart;bonus=null;clearKeys();shotCooldown=0;introTicks=60;recordEvent('gallery-end','GALLERY +'+points+' POINTS. CAMPAIGN AMMO RESTORED.',{pointsDelta:points});report();}
}
class Missile {
    constructor(level) {
        this.image = mainSprites;
        this.spriteX = 900;
        this.spriteY = 0;
        if (isLevelDark) this.spriteY = 150;
        this.level = level;
        this.width = 50;
        this.height = 30;
        this.x = this.level.player.x + this.level.player.width;
        this.y = this.level.player.y + this.level.player.height * 0.5 - this.height * 0.5;
        this.targetSet = false;
        this.target = null;
        this.speedX = 3;
        this.speedY = 0;
        this.delete = false;
        this.damage = 50;
        this.specialType = "missile";
        this.hit = false;
    }
    update() {
        // setting the target
        if (!this.targetSet) {
            this.level.enemies.forEach(enemy => {
                if (!enemy.isPowerUp && !enemy.delete && enemy.x > this.x + 40 && !this.targetSet) {
                    this.target = enemy;
                    this.targetSet = true;
                    this.speedX = 4;
                }
            });
        }

        if (this.target != null) {
            // unsetting target
            if (this.target.delete || this.target.x + this.target.width < this.x) {
                this.targetSet = false;
                this.speedX = 3;
            }

            // following target
            if (this.y >= this.target.y + this.target.height * 0.5) this.speedY = -5;
            else if (this.y + this.height * 0.5 <= this.target.y) this.speedY = 5;
            else this.speedY = 0;
        }

        this.x += this.speedX;
        this.y += this.speedY;

        if (this.x >= 840) this.delete = true;

        this.draw();
    }
    draw() {
        mainCtx.drawImage(this.image, this.spriteX, this.spriteY, this.width, this.height, this.x, this.y, this.width, this.height);
    }
}
